(() => {
 'use strict';
 const $ = s => document.querySelector(s);
 const products = window.LEJARDIN_PRODUCTS;
 const reducedMotion = matchMedia('(prefers-reduced-motion: reduce)');
 let paused = reducedMotion.matches, category = 'Todos', activeProduct = null, lastFocus = null;
 const money = n => n > 0 ? new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n) : 'Sob consulta';
 const normalize = s => s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
 const whatsapp = text => `https://wa.me/5517991421062?text=${encodeURIComponent(text)}`;
 const escapeHTML = value => String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const leafSvg = (id,blossom=false) => {
  let leaves = '';
  for(let i=0;i<12;i++) {const y=560-i*36,side=i%2?1:-1,x=240+Math.sin(i*.6)*20;leaves+=`<g transform="translate(${x} ${y}) rotate(${side*(37+i%3*6)})"><path d="M0 0 C-8-60-58-122-19-170 C35-148 60-65 0 0Z" fill="url(#${id}leaf)"/><path d="M0 0 Q-9-80-19-161" fill="none" stroke="#c2c994" stroke-opacity=".32" stroke-width="1"/></g>`;}
  let flowers='';if(blossom){for(const [x,y,r] of [[255,120,55],[105,255,38],[338,335,43]]){for(let i=0;i<9;i++)flowers+=`<ellipse cx="${x}" cy="${y-r*.48}" rx="${r*.38}" ry="${r*.75}" transform="rotate(${i*40} ${x} ${y})" fill="url(#${id}petal)"/>`;flowers+=`<circle cx="${x}" cy="${y}" r="${r*.2}" fill="#a88a45"/>`;}}
  return `<svg viewBox="0 0 480 680" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="${id}leaf" x1="0" y1="0" x2="1" y2="1"><stop stop-color="${blossom?'#acb389':'#4e7050'}"/><stop offset=".45" stop-color="${blossom?'#607c50':'#234b35'}"/><stop offset="1" stop-color="#163c2a"/></linearGradient><radialGradient id="${id}petal"><stop stop-color="#a87962"/><stop offset=".5" stop-color="#e7b6a6"/><stop offset="1" stop-color="#f4d8c5"/></radialGradient></defs><path d="M240 680 Q280 320 235 70" fill="none" stroke="${blossom?'#6c7c4c':'#4b6542'}" stroke-width="5"/>${leaves}${flowers}</svg>`;
 };
 $('.leaves-left').innerHTML=leafSvg('left');$('.leaves-right').innerHTML=leafSvg('right');$('.garden-sprigs').innerHTML=leafSvg('garden',true);
 if(!reducedMotion.matches){for(let i=0;i<9;i++){const p=document.createElement('i');p.className='petal';p.style.cssText=`--x:${15+i*9}%;--size:${9+i%4*4}px;--duration:${16+i%4*4}s;--delay:${-i*3}s`;$('.petals').append(p);}for(let i=0;i<16;i++){const p=document.createElement('i');p.className='firefly';p.style.cssText=`--x:${27+i*4.5}%;--y:${18+(i*19)%70}%;--delay:${-i*.7}s`;$('.fireflies').append(p);}}
 const observer = new IntersectionObserver(entries => entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target);}}),{threshold:.12});
 document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));document.documentElement.classList.add('js-motion');
 function render(){const term=normalize($('#search').value.trim());const filtered=products.filter(p=>(category==='Todos'||p.category===category)&&normalize(`${p.name} ${p.category} ${p.description}`).includes(term));$('#result-count').textContent=`${filtered.length} ${filtered.length===1?'criação encontrada':'criações encontradas'}`;$('#empty-state').hidden=filtered.length>0;
 $('#product-grid').innerHTML=filtered.map((p,i)=>`<article class="product-card" style="--delay:${Math.min(i*75,300)}ms"><button class="product-open" data-product="${escapeHTML(p.id)}" aria-label="Ver detalhes de ${escapeHTML(p.name)}"><img src="${p.image}" alt="${escapeHTML(p.name)}" loading="lazy" width="600" height="750"><span class="product-type">${escapeHTML(p.category)}</span><span class="product-arrow" aria-hidden="true">↗</span></button><div class="product-info"><h3><button class="product-title" data-product="${escapeHTML(p.id)}">${escapeHTML(p.name)}</button></h3><span class="product-price">${money(p.price)}</span></div><p class="product-note">${escapeHTML(p.note)}</p></article>`).join('');
 }
 document.querySelectorAll('.filter').forEach(button=>button.addEventListener('click',()=>{category=button.dataset.category;document.querySelectorAll('.filter').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});render();}));$('#search').addEventListener('input',render);$('#clear-filters').addEventListener('click',()=>{$('#search').value='';document.querySelector('[data-category="Todos"]').click();$('#search').focus();});
 const productDialog=$('#product-dialog'),occasionDialog=$('#occasion-dialog');
 function modalOpen(dialog){lastFocus=document.activeElement;dialog.showModal();document.body.classList.add('modal-open');}
 function modalClose(dialog){dialog.close();}
 function updateProductLink(){if(!activeProduct)return;let message=`Olá! Gostaria de consultar ${activeProduct.name} (referência: ${activeProduct.id}) na Le Jardin. Podem confirmar o valor, a composição e a entrega?`;const note=$('#gift-message').value.trim();if(note)message+=`\n\nRecado para acompanhar o presente: ${note}`;$('#detail-whatsapp').href=whatsapp(message);}
 function openProduct(id,changeUrl=true){const p=products.find(p=>p.id===id);if(!p)return;activeProduct=p;$('#detail-title').textContent=p.name;$('#detail-category').textContent=p.category;$('#detail-description').textContent=p.description;$('#detail-image').src=p.image;$('#detail-image').alt=p.name;$('#gift-message').value='';$('#share-status').textContent='';updateProductLink();if(!productDialog.open)modalOpen(productDialog);if(changeUrl){const url=new URL(location.href);url.searchParams.set('product',id);history.pushState(null,'',url);}}
 $('#product-grid').addEventListener('click',event=>{const target=event.target.closest('[data-product]');if(target)openProduct(target.dataset.product);});$('#gift-message').addEventListener('input',updateProductLink);
 document.querySelectorAll('dialog').forEach(dialog=>{dialog.querySelector('.dialog-close').addEventListener('click',()=>modalClose(dialog));dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)modalClose(dialog);}});dialog.addEventListener('close',()=>{document.body.classList.remove('modal-open');lastFocus?.focus();if(dialog===productDialog){activeProduct=null;const url=new URL(location.href);url.searchParams.delete('product');history.replaceState(null,'',url);}});});
 window.addEventListener('popstate',()=>{const id=new URLSearchParams(location.search).get('product');if(id)openProduct(id,false);else if(productDialog.open)productDialog.close();});
 $('#share-product').addEventListener('click',async()=>{const isLocal=location.protocol==='file:'||['localhost','127.0.0.1'].includes(location.hostname);const link=isLocal&&activeProduct?`https://lejardinfleurs.com.br/produto/${encodeURIComponent(activeProduct.id)}`:location.href;try{await navigator.clipboard.writeText(link);$('#share-status').textContent='Link copiado. Compartilhe esse carinho.';}catch{$('#share-status').textContent=`Link desta criação: ${link}`;}});
 const suggestions={'Aniversário':'Buquês, boxes e cestas para celebrar um novo ciclo. Conte para quem é o presente e a equipe ajuda a escolher.','Amor':'Rosas, tulipas e flores para uma declaração cheia de significado. Vamos encontrar o gesto que combina com vocês?','Agradecimento':'Um arranjo ou um box pode transformar a sua gratidão em um gesto especial. Consulte as composições disponíveis.','Só porque sim':'Uma surpresa no meio do dia. Um carinho sem data marcada. Converse com a equipe e descubra as flores disponíveis.'};
 document.querySelectorAll('.occasion').forEach(button=>button.addEventListener('click',()=>{const occasion=button.dataset.occasion;$('#occasion-dialog-title').textContent=occasion;$('#occasion-description').textContent=suggestions[occasion];$('#occasion-whatsapp').href=whatsapp(`Olá! Gostaria de ajuda para escolher um presente Le Jardin para a ocasião: ${occasion}. Podem me mostrar as opções disponíveis?`);modalOpen(occasionDialog);}));
 const menu=$('#mobile-menu'),menuToggle=$('.menu-toggle');function closeMenu(){menu.hidden=true;menuToggle.setAttribute('aria-expanded','false');menuToggle.setAttribute('aria-label','Abrir menu');}menuToggle.addEventListener('click',()=>{const open=menu.hidden;menu.hidden=!open;menuToggle.setAttribute('aria-expanded',String(open));menuToggle.setAttribute('aria-label',open?'Fechar menu':'Abrir menu');});menu.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!menu.hidden){closeMenu();menuToggle.focus();}});
 let frame=null;
 function onScroll(){frame=null;const y=scrollY,h=innerHeight;$('.header').classList.toggle('scrolled',y>h*.6);const max=document.documentElement.scrollHeight-h;$('.reading-progress').style.transform=`scaleX(${max>0?y/max:0})`;if(paused)return;
 const heroProgress=Math.min(y/h,1);$('.hero-art').style.transform=`translate3d(0,${heroProgress*120}px,0) scale(${1+heroProgress*.07})`;$('.leaves-left').style.transform=`translate3d(${heroProgress*50}px,${-heroProgress*70}px,0) rotate(${heroProgress*8}deg)`;$('.leaves-right').style.transform=`translate3d(${-heroProgress*50}px,${-heroProgress*80}px,0) scaleX(-1) rotate(${heroProgress*8}deg)`;
 const rect=$('.garden').getBoundingClientRect(),travel=Math.max(1,rect.height-h);const progress=Math.max(0,Math.min(1,-rect.top/travel));$('.garden-sprigs').style.transform=`translate3d(0,${(1-progress)*100}px,0) rotate(${-9+progress*12}deg) scale(${.8+progress*.25})`;}
 window.addEventListener('scroll',()=>{if(frame===null)frame=requestAnimationFrame(onScroll);},{passive:true});window.addEventListener('resize',()=>{if(innerWidth>760)closeMenu();onScroll();});
 function setMotion(value){paused=value;document.documentElement.classList.toggle('motion-paused',value);$('#motion-toggle').setAttribute('aria-pressed',String(value));$('#motion-toggle').textContent=value?'Ativar animações':'Pausar animações';if(value){$('.hero-art').style.transform='none';$('.leaves-left').style.transform='none';$('.leaves-right').style.transform='scaleX(-1)';$('.garden-sprigs').style.transform='none';}onScroll();}
 $('#motion-toggle').addEventListener('click',()=>setMotion(!paused));reducedMotion.addEventListener('change',e=>setMotion(e.matches));render();setMotion(paused);
 const initialProduct=new URLSearchParams(location.search).get('product');if(initialProduct)openProduct(initialProduct,false);
})();
